"""Original CARLA acquisition for standing, passage and two-sided sight attempts."""
from __future__ import annotations

import json
import math
import os
import queue
import shutil
import subprocess
from pathlib import Path

from native_construction import (RATE_HZ, occluder_probes, sample, sha,
                                 spawn_scene, validate_scene)


def write(path, value):
    Path(path).write_text(json.dumps(value,indent=2,allow_nan=False)+"\n")


class Cameras:
    """Four frame-joined original videos, including both statutory approaches."""
    SPECS=(("overview",1920,1080),("approach",1280,720),
           ("reference_corner",1280,720),("driver_reference",1280,720))

    def __init__(self,world,scene,output,carla):
        self.sensors=[];self.encoders={};self.queues={};self.errors=[];self.closed=False
        try:self._start(world,scene,Path(output),carla)
        except BaseException:
            self.close();raise

    def _start(self,world,scene,output,carla):
        target=(sum(scene["standing_body_xy_m"][i] for i in (0,2))/2,
                sum(scene["standing_body_xy_m"][i] for i in (1,3))/2,1.)
        distance=60.96
        positions={"overview":(0.,0.,35.),
                   "approach":(-distance,scene["sight_eye_y_m"],1.2),
                   "reference_corner":(distance,scene["sight_eye_y_m"],1.2),
                   "driver_reference":(-12.,2.2,7.)}
        library=world.get_blueprint_library()
        for name,width,height in self.SPECS:
            bp=library.find("sensor.camera.rgb")
            if bp is None:raise ValueError("Native RGB camera blueprint missing")
            for key,value in (("image_size_x",width),("image_size_y",height),("fov",75)):
                bp.set_attribute(key,str(value))
            x,y,z=positions[name]
            dx,dy,dz=target[0]-x,target[1]-y,target[2]-z
            yaw=math.degrees(math.atan2(dy,dx))
            pitch=math.degrees(math.atan2(dz,math.hypot(dx,dy)))
            sensor=world.spawn_actor(bp,carla.Transform(carla.Location(x=x,y=y,z=z),
                                                       carla.Rotation(pitch=pitch,yaw=yaw)))
            if sensor is None:raise RuntimeError("Native camera spawn failed: "+name)
            self.sensors.append(sensor)
            frames=queue.Queue(maxsize=4);self.queues[name]=frames
            def receive(image,q=frames,label=name):
                try:q.put_nowait(image)
                except queue.Full:self.errors.append("camera overflow: "+label)
            sensor.listen(receive)
            process=subprocess.Popen(["ffmpeg","-nostdin","-hide_banner","-loglevel","error","-n",
                "-f","rawvideo","-pixel_format","bgra","-video_size",f"{width}x{height}",
                "-framerate",str(RATE_HZ),"-i","pipe:0","-an","-c:v","ffv1","-pix_fmt","bgra",
                str(output/(name+".mkv"))],stdin=subprocess.PIPE,stderr=subprocess.DEVNULL)
            self.encoders[name]=process

    def append(self,frame):
        if self.errors:raise RuntimeError("; ".join(self.errors))
        for name,_,_ in self.SPECS:
            image=self.queues[name].get(timeout=15)
            if image.frame!=frame:raise RuntimeError(name+" camera/world frame mismatch")
            self.encoders[name].stdin.write(image.raw_data)

    def close(self):
        if self.closed:return
        self.closed=True;errors=[]
        for sensor in reversed(self.sensors):
            try:sensor.stop()
            except BaseException as exc:errors.append(repr(exc))
        for name,process in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed:process.stdin.close()
                if process.wait(timeout=180)!=0:errors.append("encoder failed: "+name)
            except BaseException as exc:errors.append(repr(exc))
        for sensor in reversed(self.sensors):
            try:sensor.destroy()
            except BaseException as exc:errors.append(repr(exc))
        if errors:raise RuntimeError("; ".join(errors))


def run_native(scene,output,host,port,map_source,scene_path):
    # Keep imported pipeline module side effects within a worker scratch root.
    root=Path(__file__).resolve().parents[2]
    safe_root=(root/".runtime-work").resolve()
    if not os.environ.get("SCENARIO_PIPELINE_OUTPUT_ROOT"):
        os.environ["SCENARIO_PIPELINE_OUTPUT_ROOT"]=str(safe_root/"c135705-native-runtime")
    if not Path(os.environ["SCENARIO_PIPELINE_OUTPUT_ROOT"]).resolve().is_relative_to(safe_root):
        raise ValueError("pipeline output root must be under .runtime-work")
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap,seal_capture
    from worker_exchange.world_restore import fields,equal

    validate_scene(scene,map_source)
    output=Path(output).resolve()
    if not output.is_dir() or not output.is_relative_to(safe_root):
        raise ValueError("fresh Native attempt directory under .runtime-work required")
    if any((output/name).exists() for name in ("trace.jsonl","video_frames.jsonl",
                                              "capture-seal.json","standing-body-history.jsonl")):
        raise ValueError("Native attempt already contains original acquisition")
    client=carla.Client(host,port);client.set_timeout(30)
    old_world=client.get_world();old_map=old_world.get_map().name
    if not old_map or old_map.startswith("OpenDriveMap"):
        raise ValueError("original world needs a loadable CARLA map for restoration")
    old_settings=old_world.get_settings()
    world=None;actors=[];cameras=capture=frame_map=None
    frames=[];phase="initializing";error=None;restored=False
    try:
        source=Path(map_source)
        if sha(source)!=scene["map_source_sha256"]:raise ValueError("authored map changed")
        if not (output/"construction.json").is_file() or not (output/"runner.py").is_file():
            raise ValueError("runtime materialized construction and runner required")
        if Path(scene_path).resolve()!=output/"scene.json":
            raise ValueError("Native scene must be materialized in the attempt")
        shutil.copyfile(source,output/"authored-road.xodr")
        world=client.generate_opendrive_world(source.read_text())
        settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05
        world.apply_settings(settings)
        standing,passing,props,actors=spawn_scene(world,scene,carla)
        write(output/"acquisition-provenance.json",{
            "provenance_kind":"native","diagnostic_fixture":False,
            "method":"original CARLA live acquisition from source-hashed worker OpenDRIVE",
            "authored_road_sha256":sha(output/"authored-road.xodr")})
        write(output/"occluder-live-initial.json",occluder_probes(scene,props))
        cameras=Cameras(world,scene,output,carla)
        capture=PipelineCapture(client,standing,output,scene["case_id"])
        frame_map=FrameMap(output/"video_frames.jsonl")
        phase="capturing"
        with (output/"standing-body-history.jsonl").open("x",buffering=1) as standing_file,\
             (output/"passing-body-history.jsonl").open("x",buffering=1) as passing_file,\
             (output/"occluder-body-history.jsonl").open("x",buffering=1) as props_file,\
             (output/"mechanical-attempt-history.jsonl").open("x",buffering=1) as mechanism_file:
            for index in range(round(scene["duration_s"]*RATE_HZ)):
                # The requested constant velocity is a controller command; the
                # measured original pose/velocity/body is retained independently.
                passing.set_target_velocity(carla.Vector3D(x=-16.0,y=0.,z=0.))
                frame=world.tick();snapshot=world.get_snapshot()
                if frame!=snapshot.frame:raise RuntimeError("Native world frame mismatch")
                time_s=snapshot.timestamp.elapsed_seconds
                capture.capture(frame,time_s)
                cameras.append(frame)
                frame_map.append(frame,time_s)
                standing_file.write(json.dumps(sample(standing,snapshot),allow_nan=False)+"\n")
                passing_file.write(json.dumps(sample(passing,snapshot),allow_nan=False)+"\n")
                props_file.write(json.dumps({"frame":frame,"time_s":time_s,
                    "actors":[sample(prop,snapshot) for prop in props]},allow_nan=False)+"\n")
                mechanism_file.write(json.dumps({"frame":frame,"time_s":time_s,
                    "standing_actor_id":int(standing.id),"engine_disabled_by_worker":True,
                    "physics_disabled_by_worker":True,"brake_requested":1.,
                    "hand_brake_requested":True,"duration_since_first_sample_s":index/RATE_HZ,
                    "unavoidable_stop_verified":False},allow_nan=False)+"\n")
                frames.append(frame)
        phase="closing"
        capture.close();capture=None
        frame_map.close();frame_map=None
        cameras.close();cameras=None
        names=("scene.json","trace.jsonl","video_frames.jsonl","road.xodr","authored-road.xodr",
               "carla_recorder.log","standing-body-history.jsonl","passing-body-history.jsonl",
               "occluder-body-history.jsonl","mechanical-attempt-history.jsonl",
               "occluder-live-initial.json",*(name+".mkv" for name,_,_ in Cameras.SPECS))
        write(output/"acquisition.json",{name:{"kind":"original_native","sha256":sha(output/name)}
                                          for name in names})
        phase="sealed"
    except BaseException as exc:
        error=repr(exc);raise
    finally:
        cleanup=[]
        for resource in (capture,frame_map,cameras):
            if resource is not None:
                try:resource.close()
                except BaseException as exc:cleanup.append(repr(exc))
        for actor in reversed(actors):
            try:actor.destroy()
            except BaseException as exc:cleanup.append(repr(exc))
        try:
            # generate_opendrive_world changes the loaded world; reload and
            # verify the original settings before any capture can be sealed.
            restored_world=client.load_world(old_map)
            restored_world.apply_settings(old_settings)
            restored=all(equal(fields(restored_world.get_settings()).get(k),v)
                         for k,v in fields(old_settings).items())
            restored=restored and restored_world.get_map().name==old_map
        except BaseException as exc:cleanup.append(repr(exc))
        if phase=="sealed" and not cleanup and restored:
            seal_capture(output,frames=len(frames),restoration={
                "restored":True,"settings_readback":"original map and settings restored"},
                errors=[],encoder_exit_codes={name:0 for name,_,_ in Cameras.SPECS},
                context={"authored_road_sha256":sha(output/"authored-road.xodr"),
                         "case_id":scene["case_id"]})
        else:
            write(output/"native-run-status.json",{"phase":phase,"errors":[e for e in [error,*cleanup] if e],
                                                   "original_world_restored":restored})
            if phase=="sealed":raise RuntimeError("Native cleanup or world restoration failed")

"""CPU geometry for standing width, actual passage and two-sided 200 ft sight lines.

This measures physical candidate scenes only. District, practicability, disability
and legal adequacy remain separately sourced judgment questions.
"""
from __future__ import annotations

import math

FEET_TO_METRES = 0.3048
STATUTORY_SIGHT_DISTANCE_M = 200 * FEET_TO_METRES


def rectangle(value, name):
    if (not isinstance(value, (list, tuple)) or len(value) != 4 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in value) or
            value[0] >= value[2] or value[1] >= value[3]):
        raise ValueError("invalid finite rectangle: " + name)
    return tuple(float(v) for v in value)


def overlaps(a, b):
    a, b = rectangle(a, "first"), rectangle(b, "second")
    return a[0] < b[2] and b[0] < a[2] and a[1] < b[3] and b[1] < a[3]


def segment_crosses_rect(start, end, rect):
    """Liang-Barsky closed-segment test; touching occluder counts as obscured."""
    x0,y0 = start; x1,y1 = end
    rect = rectangle(rect, "occluder")
    if any(type(v) not in (int,float) or not math.isfinite(v) for v in (*start,*end)):
        raise ValueError("nonfinite sight endpoint")
    dx,dy = x1-x0,y1-y0
    lo,hi = 0.0,1.0
    for p,q in ((-dx,x0-rect[0]),(dx,rect[2]-x0),(-dy,y0-rect[1]),(dy,rect[3]-y0)):
        if p == 0:
            if q < 0:return False
        else:
            t=q/p
            if p < 0:lo=max(lo,t)
            else:hi=min(hi,t)
            if lo > hi:return False
    return True


def measure(scene):
    road = rectangle(scene["paved_road_xy_m"], "paved road")
    standing = rectangle(scene["standing_body_xy_m"], "standing body")
    if not (road[0] <= standing[0] and standing[2] <= road[2]):
        raise ValueError("standing body outside authored road length")
    direction = scene["standing_side"]
    if direction not in ("negative_y", "positive_y"):
        raise ValueError("unknown standing side")
    opposite_width = road[3]-standing[3] if direction=="negative_y" else standing[1]-road[1]
    if opposite_width < 0:
        opposite_width = 0.0
    route = scene["other_vehicle_centers_xy_m"]
    if not isinstance(route,list) or len(route)<3:
        raise ValueError("passing vehicle route needs original trajectory samples")
    half_length,half_width = scene["other_vehicle_half_length_m"],scene["other_vehicle_half_width_m"]
    if not all(type(v) in (int,float) and math.isfinite(v) and v>0 for v in (half_length,half_width)):
        raise ValueError("invalid passing vehicle dimensions")
    bodies = [[x-half_length,y-half_width,x+half_length,y+half_width] for x,y in route]
    collisions=[i for i,body in enumerate(bodies) if overlaps(body,standing)]
    outside=[i for i,body in enumerate(bodies)
             if body[0]<road[0] or body[2]>road[2] or body[1]<road[1] or body[3]>road[3]]
    eye_y = scene["sight_eye_y_m"]
    target = [(standing[0]+standing[2])/2,(standing[1]+standing[3])/2]
    occluders=[rectangle(value,"sight occluder") for value in scene.get("sight_occluders_xy_m",[])]
    probes={}
    for side in (-1,1):
        for distance in scene["sight_probe_distances_m"]:
            if type(distance) not in (int,float) or not math.isfinite(distance) or distance<=0:
                raise ValueError("invalid sight probe distance")
            eye=(side*float(distance),float(eye_y))
            blockers=[i for i,rect in enumerate(occluders) if segment_crosses_rect(eye,target,rect)]
            probes[f"{'negative_x' if side<0 else 'positive_x'}:{distance:.3f}m"]={
                "eye_xy_m":eye,"target_xy_m":target,"visible":not blockers,
                "occluder_indices":blockers}
    return {"statutory_sight_distance_m":STATUTORY_SIGHT_DISTANCE_M,
            "unobstructed_opposite_width_m":opposite_width,
            "passing_body_collision_frames":collisions,
            "passing_body_outside_paved_frames":outside,
            "physical_passage_observed":not collisions and not outside,
            "sight_probes":probes,
            "legal_adequacy_judgment":"unresolved",
            "district_status":"requires separate administrative source",
            "disability_exception":"requires separate actor and duration evidence"}

"""Independent saved-source audit for each C135705 Native attempt.

It rejects missing, stale or inconsistent original evidence and checks the
requested physical contrast. It does not assert legal or optical acceptance.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import math
from pathlib import Path

from native_construction import ASSIGNMENT
from saved_measurement import SOURCES,VIDEOS,body_rect,rows


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def audit(attempt, *, diagnostic_test=False):
    root=Path(attempt).resolve()
    report_path=root/"standing-measurement.json"
    if not report_path.is_file():raise ValueError("missing saved-only standing measurement")
    report=json.loads(report_path.read_text())
    scene=json.loads((root/"scene.json").read_text())
    case=scene.get("case_id")
    if not case.startswith(ASSIGNMENT+"__") or report.get("case_id")!=case:
        raise ValueError("exact case binding differs")
    seal=root/"capture-seal.json"
    if report.get("capture_seal_sha256")!=sha(seal):raise ValueError("stale capture seal")
    sealed=json.loads(seal.read_text())
    expected_kind="synthetic_fixture" if diagnostic_test else "native"
    if (sealed.get("format")!="worker-sealed-capture" or
        sealed.get("provenance_kind")!=expected_kind or
        sealed.get("diagnostic_fixture") is not diagnostic_test or
        sealed.get("restoration",{}).get("restored") is not True):
        raise ValueError("capture seal provenance or restoration differs")
    provenance=json.loads((root/"acquisition-provenance.json").read_text())
    if provenance.get("provenance_kind")!=expected_kind or provenance.get("diagnostic_fixture") is not diagnostic_test:
        raise ValueError("acquisition provenance differs")
    if report.get("provenance_kind")!=expected_kind or report.get("physical_acceptance_claimed") is not False:
        raise ValueError("measurement provenance or physical claim differs")
    source_hashes=report.get("source_sha256",{})
    for name in (*SOURCES,*VIDEOS,"acquisition.json"):
        if source_hashes.get(name)!=sha(root/name):
            raise ValueError("missing or stale original source: "+name)
        if name in sealed.get("sources",{}) and sealed["sources"][name]!=source_hashes[name]:
            raise ValueError("sealed original source changed: "+name)
    measured=report.get("measured",{})
    result=json.loads((root/"result.json").read_text())
    if result.get("measured_values")!=measured or result.get("case_id")!=case:
        raise ValueError("saved result differs from original measurement")
    mapping=rows(root/"video_frames.jsonl")
    standing=rows(root/"standing-body-history.jsonl")
    passing=rows(root/"passing-body-history.jsonl")
    props=rows(root/"occluder-body-history.jsonl")
    mechanical=rows(root/"mechanical-attempt-history.jsonl")
    count=measured.get("frame_count")
    if count!=sealed.get("frames") or any(len(x)!=count for x in (mapping,standing,passing,props,mechanical)):
        raise ValueError("original frame count differs")
    for index,group in enumerate(zip(mapping,standing,passing,props,mechanical)):
        frame=group[0].get("carla_frame");time=group[0].get("time_s")
        if group[0].get("video_frame")!=index or any(r.get("frame")!=frame or
            not math.isclose(r.get("time_s",math.inf),time,abs_tol=1e-4) for r in group[1:]):
            raise ValueError("original frame/time identity failed")
        if mechanical[index].get("standing_actor_id")!=standing[index].get("actor_id"):
            raise ValueError("mechanical failure actor identity failed")
        body_rect(standing[index]);body_rect(passing[index])
        if len(props[index].get("actors",[]))!=len(scene.get("sight_occluders_xy_m",[])):
            raise ValueError("physical occluder actors missing")
        for prop in props[index]["actors"]:body_rect(prop)
    media=report.get("media_full_decode",{})
    for name in VIDEOS:
        receipt=media.get(name,{})
        if receipt.get("sha256")!=source_hashes[name] or receipt.get("frames_fully_decoded")!=count or receipt.get("fps")!=20:
            raise ValueError("missing full media decode receipt: "+name)
    if measured.get("statutory_sight_distance_m")!=60.96 or measured.get("legal_verdict_claimed") is not False:
        raise ValueError("numeric sight boundary or verdict claim invalid")
    if not measured.get("standing_stationary_engineering_check") or not measured.get("mechanical_disable_and_brake_attempt_observed"):
        raise ValueError("standing actor or failure mechanism not observed")
    sight=measured.get("sight_probes",{})
    pair=[sight.get(f"{side}:60.960m",{}).get("clear_xy_geometry") for side in ("negative_x","positive_x")]
    suffix=case.removeprefix(ASSIGNMENT+"__")
    if suffix=="passage_clear_view":
        expected=measured.get("physical_passage_observed") is True and pair==[True,True]
    elif suffix=="passage_blocked":
        expected=(measured.get("physical_passage_observed") is False and
                  measured.get("opposite_route_corridor_interference") is True and pair==[True,True])
    elif suffix=="view_occluded_both":
        expected=measured.get("physical_passage_observed") is True and pair==[False,False] and len(measured.get("actual_prop_bodies_xy_m",[]))==2
    else:raise ValueError("unknown exact case")
    if not expected:raise ValueError("requested physical contrast not measured")
    if not all(item.get("matched") is True for item in result.get("target_checks",[])):
        raise ValueError("saved physical target check not matched")
    return {"format":"worker-delivery-audit","case_id":case,"status":"cpu_source_audit_passed",
            "measurement_sha256":sha(report_path),"capture_seal_sha256":sha(seal),
            "frame_count":count,"original_source_hashes":source_hashes,
            "physical_acceptance_claimed":False,"diagnostic_audit_test_passed":diagnostic_test,
            "optical_visibility":"requires live image review",
            "legal_verdict_claimed":False}


def main():
    parser=argparse.ArgumentParser();parser.add_argument("attempt")
    args=parser.parse_args();print(json.dumps(audit(args.attempt),indent=2))


if __name__=="__main__":main()

"""Independent exact-pair audit for C135705 contrast consistency."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from delivery_audit import audit as audit_delivery

PAIRS={"passage_width_with_fixed_view":("passage_clear_view","passage_blocked"),
       "two_sided_visibility_with_fixed_passage":("passage_clear_view","view_occluded_both")}


def audit(comparison_id,left,right,*,diagnostic_test=False):
    if comparison_id not in PAIRS:raise ValueError("unknown comparison")
    a,b=[Path(x).resolve() for x in (left,right)]
    receipts=[audit_delivery(path,diagnostic_test=diagnostic_test) for path in (a,b)]
    if [r["case_id"].rsplit("__",1)[1] for r in receipts]!=list(PAIRS[comparison_id]):
        raise ValueError("exact case pair/order differs")
    scenes=[json.loads((path/"scene.json").read_text()) for path in (a,b)]
    measurements=[json.loads((path/"standing-measurement.json").read_text())["measured"] for path in (a,b)]
    fixed=("map_source_sha256","paved_road_xy_m","shoulder_negative_y_xy_m",
           "shoulder_positive_y_xy_m","other_vehicle_centers_xy_m",
           "other_vehicle_half_length_m","other_vehicle_half_width_m",
           "sight_eye_y_m","sight_probe_distances_m","standing_blueprint_id",
           "passing_blueprint_id","disabled_physical_mechanism")
    if any(scenes[0][key]!=scenes[1][key] for key in fixed):
        raise ValueError("declared fixed construction condition changed")
    if comparison_id=="passage_width_with_fixed_view":
        if scenes[0]["sight_occluders_xy_m"]!=scenes[1]["sight_occluders_xy_m"]:
            raise ValueError("sight occluders changed in width comparison")
        if not (measurements[0]["minimum_unobstructed_opposite_width_m"]>
                measurements[1]["minimum_unobstructed_opposite_width_m"]):
            raise ValueError("measured opposite width contrast absent")
        if not measurements[0]["physical_passage_observed"] or measurements[1]["physical_passage_observed"]:
            raise ValueError("measured passage contrast absent")
    else:
        if scenes[0]["standing_body_xy_m"]!=scenes[1]["standing_body_xy_m"]:
            raise ValueError("standing body changed in visibility comparison")
        if not all(m["physical_passage_observed"] for m in measurements):
            raise ValueError("passage not fixed in sight comparison")
        if not scenes[1]["sight_occluders_xy_m"] or scenes[0]["sight_occluders_xy_m"]:
            raise ValueError("sight occluder construction contrast absent")
    return {"format":"worker-comparison-audit","comparison_id":comparison_id,
            "case_ids":[r["case_id"] for r in receipts],"status":"cpu_source_audit_passed",
            "fixed_conditions_checked":list(fixed),"physical_acceptance_claimed":False}


def main():
    parser=argparse.ArgumentParser();parser.add_argument("comparison_id");parser.add_argument("left");parser.add_argument("right")
    parser.add_argument("--diagnostic-test",action="store_true")
    args=parser.parse_args();print(json.dumps(audit(args.comparison_id,args.left,args.right,
                                                diagnostic_test=args.diagnostic_test),indent=2))


if __name__=="__main__":main()
